-- load_movement_staging.sql
-- Generated by scripts/make_wwi_jobs.py: edit WWI_JOBS there and rerun it, rather than editing this file.
-- Fills WideWorldImportersDW.Integration.Movement_Staging the way Microsoft's SSIS package would,
-- so Integration.MigrateStagedMovementData has input to work on.
-- Run against WideWorldImportersDW. Needs the WideWorldImporters (shop) database on the same server.

SET NOCOUNT ON;

-- 1. Pick a time window: @WindowMonths long, ending @MonthsBack months before the warehouse's last load.
--    The default is the dev batch; jobs/movement.json changes it for the holdout.
DECLARE @MonthsBack   int = 0;
DECLARE @WindowMonths int = 1;
DECLARE @LastLoad   datetime2(7) = (SELECT [Cutoff Time] FROM Integration.[ETL Cutoff] WHERE [Table Name] = N'Movement');
DECLARE @NewCutoff  datetime2(7) = DATEADD(month, -@MonthsBack, @LastLoad);
DECLARE @LastCutoff datetime2(7) = DATEADD(month, -@WindowMonths, @NewCutoff);

-- 2. Clear staging (in-memory tables don't allow TRUNCATE)
DELETE FROM Integration.Movement_Staging;

-- 3. Pull the rows from the shop database. In-memory tables can't be written in the same
--    statement as another user database, so go through a temp table.
CREATE TABLE #rows (
    [Date Key] date,
    [WWI Stock Item Transaction ID] int,
    [WWI Invoice ID] int,
    [WWI Purchase Order ID] int,
    [Quantity] int,
    [WWI Stock Item ID] int,
    [WWI Customer ID] int,
    [WWI Supplier ID] int,
    [WWI Transaction Type ID] int,
    [Transaction Occurred When] datetime2(7)
);

INSERT INTO #rows
EXEC WideWorldImporters.Integration.GetMovementUpdates @LastCutoff = @LastCutoff, @NewCutoff = @NewCutoff;

-- Microsoft's staging table names these columns differently: [Transaction Occurred When] -> [Last Modifed When]
INSERT INTO Integration.Movement_Staging ([Date Key], [WWI Stock Item Transaction ID], [WWI Invoice ID], [WWI Purchase Order ID], [Quantity], [WWI Stock Item ID], [WWI Customer ID], [WWI Supplier ID], [WWI Transaction Type ID], [Last Modifed When])
SELECT [Date Key], [WWI Stock Item Transaction ID], [WWI Invoice ID], [WWI Purchase Order ID], [Quantity], [WWI Stock Item ID], [WWI Customer ID], [WWI Supplier ID], [WWI Transaction Type ID], [Transaction Occurred When]
FROM #rows;

DROP TABLE #rows;

-- 4. Open a lineage record. MigrateStagedMovementData looks for one with no completion time.
EXEC Integration.GetLineageKey @TableName = N'Movement', @NewCutoffTime = @NewCutoff;

-- 5. Report what got staged
SELECT COUNT(*) AS staged_rows, @LastCutoff AS window_from, @NewCutoff AS window_to
FROM Integration.Movement_Staging;
